import OpenAI from 'openai';
import { OpenAIStream, StreamingTextResponse } from 'ai';

// Utilisation du runtime 'edge' pour des performances optimales sur les fonctions Vercel
export const runtime = 'edge';

/**
 * Route API pour le chat IA WinCore
 * Supporte le streaming de texte pour une expérience utilisateur fluide
 */
export async function POST(req) {
  try {
    const { messages } = await req.json();

    // Initialisation du client OpenAI avec la clé d'environnement spécifiée
    const openai = new OpenAI({
      apiKey: process.env.OPENAI_API_KEY,
    });

    // Création de la complétion avec le modèle gpt-4o-mini
    const response = await openai.chat.completions.create({
      model: 'gpt-4o-mini',
      stream: true,
      messages: messages.map(m => ({
        // Adaptation du format de message si nécessaire (rôle 'model' -> 'assistant')
        role: m.role === 'model' ? 'assistant' : m.role,
        content: m.content || m.text,
      })),
      temperature: 0.7,
      max_tokens: 1000,
    });

    // Transformation de la réponse en un flux (stream) lisible
    const stream = OpenAIStream(response);

    // Retourne une réponse en streaming au frontend
    return new StreamingTextResponse(stream);
  } catch (error) {
    console.error('AI Chat Error:', error);
    return new Response(
      JSON.stringify({ 
        error: 'Une erreur est survenue lors de la communication avec le service IA.',
        details: error.message 
      }), 
      { 
        status: 500, 
        headers: { 'Content-Type': 'application/json' } 
      }
    );
  }
}

