import { GoogleGenAI } from "@google/genai";

export const config = {
  runtime: 'edge',
};

export default async function handler(req) {
  // Gestion des méthodes autorisées
  if (req.method !== 'POST') {
    return new Response('Method Not Allowed', { status: 405 });
  }

  try {
    const { messages } = await req.json();

    // Récupération de la clé API (Doit être définie dans les variables d'env Vercel sous le nom API_KEY ou GEMINI_API_KEY)
    const apiKey = process.env.API_KEY || process.env.GEMINI_API_KEY;

    if (!apiKey) {
      return new Response(JSON.stringify({ error: 'API Key not configured' }), { 
        status: 500,
        headers: { 'Content-Type': 'application/json' }
      });
    }

    const ai = new GoogleGenAI({ apiKey });

    // Conversion de l'historique pour Gemini
    // Le SDK Vercel AI envoie { role: 'user'|'assistant', content: string }
    // Gemini attend { role: 'user'|'model', parts: [{ text: string }] }
    const history = messages.slice(0, -1).map(m => ({
      role: m.role === 'assistant' ? 'model' : 'user',
      parts: [{ text: m.content }]
    }));

    const lastMessage = messages[messages.length - 1].content;

    // Instructions système
    const systemInstruction = `
      Ton nom est Corey, l'assistant cybernétique de WinCore Tech. 
      Ton créateur est Zadeck Hexmoor.
      Ton ton doit être futuriste, intelligent, pro et légèrement teinté d'un style "IA avancée".
      Réponds exclusivement en français.
      Oriente vers WhatsApp (${process.env.WHATSAPP || "+229 01 93 42 84 16"}) pour les achats.
    `;

    // Création du flux de réponse
    const stream = new ReadableStream({
      async start(controller) {
        try {
          const chat = ai.chats.create({
            model: 'gemini-2.5-flash-latest', // Modèle rapide et efficace
            config: {
              systemInstruction: systemInstruction,
              temperature: 0.7,
            },
            history: history
          });

          const result = await chat.sendMessageStream({ message: lastMessage });

          for await (const chunk of result) {
            const text = chunk.text;
            if (text) {
              controller.enqueue(new TextEncoder().encode(text));
            }
          }
          controller.close();
        } catch (error) {
          console.error("Stream Error:", error);
          controller.error(error);
        }
      }
    });

    return new Response(stream, {
      headers: {
        'Content-Type': 'text/plain; charset=utf-8',
        'Cache-Control': 'no-cache',
        'Connection': 'keep-alive',
      },
    });

  } catch (error) {
    console.error('API Error:', error);
    return new Response(JSON.stringify({ error: error.message }), { 
      status: 500,
      headers: { 'Content-Type': 'application/json' }
    });
  }
}

